3	#include "memory_region.hpp"
4	
5	#include <fmt/format.h>
6	#include <spdlog/spdlog.h>
7	#include <systemc>
8	#include <tlm>
9	#include <tlm_utils/multi_passthrough_initiator_socket.h>
10	#include <tlm_utils/multi_passthrough_target_socket.h>
