17	/**
18	 * An interconnect that routes transactions based on memory regions.
19	 * Uses plain TLM2.0 base protocol types — no AXI/AHB dependency.
20	 */
21	template<std::size_t BusWidth>
22	class Interconnect : public sc_core::sc_module
23	{
24	  using this_type = Interconnect<BusWidth>;
25	  using protocol_types = tlm::tlm_base_protocol_types;
26	
27	  using base_initiator_socket =
28	    tlm::tlm_base_initiator_socket<BusWidth,
29	                                   tlm::tlm_fw_transport_if<protocol_types>,
30	                                   tlm::tlm_bw_transport_if<protocol_types>>;
31	
32	  using base_target_socket =
33	    tlm::tlm_base_target_socket<BusWidth,
34	                                tlm::tlm_fw_transport_if<protocol_types>,
35	                                tlm::tlm_bw_transport_if<protocol_types>>;
36	
37	  tlm_utils::
38	    multi_passthrough_initiator_socket<this_type, BusWidth, protocol_types>
39	      initiator_sockets{"initiator_sockets"};
40	
41	  tlm_utils::
42	    multi_passthrough_target_socket<this_type, BusWidth, protocol_types>
43	      target_sockets{"target_sockets"};
44	
45	  std::map<const tlm::tlm_generic_payload*, unsigned> trans_map;
46	  using fw_if = tlm::tlm_fw_transport_if<protocol_types>;
47	  std::vector<std::tuple<MemoryRegion, fw_if*, std::string>> memory_regions;
48	  std::vector<std::tuple<MemoryRegion, std::string>> reserved_regions;
49	  std::set<fw_if*> bound_targets;
50	
51	  auto find_fw_if_from_address(const uint64_t addr) -> fw_if*
52	  {
53	    for (const auto& [mr, socket, _]: this->memory_regions) {
54	      if (mr.contains(addr))
55	        return socket;
56	    }
57	
58	    return nullptr;
59	  }
60	
61	  auto nb_transport_fw(const int id,
62	                       tlm::tlm_generic_payload& trans,
63	                       tlm::tlm_phase& phase,
64	                       sc_core::sc_time& delay) -> tlm::tlm_sync_enum
65	  {
66	    const auto addr = trans.get_address();
67	    assert(id >= 0 && unsigned(id) < this->target_sockets.size());
68	    const auto target = this->find_fw_if_from_address(addr);
69	    if (!target) {
70	      spdlog::critical("target socket not found for address {:#x}, "
71	                       "initiator_port={}, cmd={}, len={}",
72	                       addr, id, trans.is_read() ? "read" : "write",
73	                       trans.get_data_length());
74	      trans.set_response_status(tlm::TLM_ADDRESS_ERROR_RESPONSE);
75	      return tlm::tlm_sync_enum::TLM_COMPLETED;
76	    }
77	
78	    const auto sync = target->nb_transport_fw(trans, phase, delay);
79	    if (sync != tlm::TLM_COMPLETED) {
80	      this->trans_map[&trans] = id;
81	    }
82	    return sync;
83	  }
84	
85	  auto nb_transport_bw(const int id,
86	                       tlm::tlm_generic_payload& trans,
87	                       tlm::tlm_phase& phase,
88	                       sc_core::sc_time& delay) -> tlm::tlm_sync_enum
89	  {
90	    assert(id >= 0 && unsigned(id) < this->initiator_sockets.size());
91	    const auto tsckt_id = this->trans_map.at(&trans);
92	    assert(tsckt_id < this->target_sockets.size());
93	
94	    const auto sync =
95	      this->target_sockets[tsckt_id]->nb_transport_bw(trans, phase, delay);
96	
97	    if (sync == tlm::TLM_COMPLETED) {
98	      this->trans_map.erase(&trans);
99	    }
100	    return sync;
101	  }
102	
103	  void b_transport(const int id,
104	                   tlm::tlm_generic_payload& trans,
105	                   sc_core::sc_time& delay)
106	  {
107	    const auto addr = trans.get_address();
108	    assert(id >= 0 && unsigned(id) < this->target_sockets.size());
109	    const auto target = this->find_fw_if_from_address(addr);
110	    if (!target) {
111	      spdlog::critical("target socket not found for address {:#x}, "
112	                       "initiator_port={}, cmd={}, len={}",
113	                       addr, id, trans.is_read() ? "read" : "write",
114	                       trans.get_data_length());
115	      trans.set_response_status(tlm::TLM_ADDRESS_ERROR_RESPONSE);
116	      return;
117	    }
118	    target->b_transport(trans, delay);
119	  }
120	
121	  bool has_overlaps(const MemoryRegion& in_mr)
122	  {
123	    for (const auto& [mr, _, __]: this->memory_regions)
124	      if (mr.overlaps(in_mr))
125	        return true;
126	    for (const auto& [mr, _]: this->reserved_regions)
127	      if (mr.overlaps(in_mr))
128	        return true;
129	    return false;
130	  }
131	
132	public:
133	  Interconnect(const sc_core::sc_module_name& name)
134	      : sc_core::sc_module{name}
135	  {
136	    this->target_sockets.register_nb_transport_fw(
137	      this, &Interconnect::nb_transport_fw);
138	    this->target_sockets.register_b_transport(this, &Interconnect::b_transport);
139	    this->initiator_sockets.register_nb_transport_bw(
140	      this, &Interconnect::nb_transport_bw);
141	  }
142	
143	  void bind_initiator(base_initiator_socket& initiator)
144	  {
145	    initiator.bind(this->target_sockets);
146	  }
147	
148	  void bind_target_no_check(base_target_socket& target, const MemoryRegion& mr)
149	  {
150	    auto* fw_if = &target.get_base_interface();
151	    if (bound_targets.find(fw_if) == bound_targets.end()) {
152	      this->initiator_sockets.bind(target);
153	      bound_targets.insert(fw_if);
154	    }
155	    memory_regions.emplace_back(
156	      std::make_tuple(mr, fw_if, std::string(target.name())));
157	  }
158	
159	  // Forward memory accesses within the specified region (mr) to the given
160	  // target for processing.
161	  void bind_target(base_target_socket& target, const MemoryRegion& mr)
162	  {
163	    if (has_overlaps(mr))
164	      throw std::invalid_argument(std::format(
165	        "invalid memory region: [{:#x}-{:#x}], overlapped with existing memory regions",
166	        mr.base_address, mr.end_address));
167	    bind_target_no_check(target, mr);
168	  }
169	
170	  // Reserve a memory region to prevent it from being bound as a target.
171	  void reserve_region(const std::string& name, const MemoryRegion& mr)
172	  {
173	    reserved_regions.push_back({mr, name});
174	  }
175	
176	  void dump_region()
177	  {
178	    fmt::print("=== Memory Regions ===\n");
179	    for (size_t i = 0; i < memory_regions.size(); ++i) {
180	      const auto& [mr, socket, name] = memory_regions[i];
181	      fmt::print("{}: [{:#x}-{:#x}] (size: {:#x})\n", name, mr.base_address,
182	                 mr.end_address, mr.end_address - mr.base_address + 1);
183	    }
184	
185	    for (size_t i = 0; i < reserved_regions.size(); ++i) {
186	      const auto& [mr, name] = reserved_regions[i];
187	      fmt::print("{}: [{:#x}-{:#x}] (size: {:#x})\n", name, mr.base_address,
188	                 mr.end_address, mr.end_address - mr.base_address + 1);
189	    }
190	  }
191	};
