1	// EngineDescriptor: the parsed result of an engine's `--describe` (or its
2	// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
3	// future engines (alioth, sid) speak to join the framework -- see
4	// docs/engine_interface.md. The framework keeps zero per-engine code; every
5	// capability it needs comes from here.
6	#ifndef ANDESIM_ENGINE_DESCRIPTOR_HPP
7	#define ANDESIM_ENGINE_DESCRIPTOR_HPP
8	
9	#include <string>
10	#include <string_view>
11	#include <vector>
12	
13	#include "json.hpp"
14	
15	namespace andes_sim {
16	
17	// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
18	// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
19	// plan executor (F6).
20	struct EngineInvoke {
21	  std::string role;
22	  std::vector<std::string> argv;
23	};
24	
25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // RVV params; 0 = not reported
30	  long dlen = 0;
31	  long elen = 0;
32	  long xlen = 0;
33	  long ilm_size = 0;                    // hart-0 local memories, BYTES; 0 = the
34	  long dlm_size = 0;                    // engine has none -> LM transport off
35	  long hvm_size = 0;                    // cluster HVM, BYTES; same contract
36	  std::vector<std::string> triggers;    // marker | pc
37	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
38	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
39	  std::vector<std::string> andes_csrs;  // Andes CSRs this engine implements; the
40	                                        // --verify gate (empty = compare all)
41	  std::vector<EngineInvoke> invoke;     // argv template per role
42	  std::string result;                   // stderr:<re> | state.mcycle
43	
44	  // Filled by the registry, not present in the JSON:
45	  std::string bin_path;                 // resolved path to the binary
46	  std::string source;                   // built-in | --describe | sidecar
47	
48	  const std::vector<std::string>* invoke_for(std::string_view role) const {
49	    for (const EngineInvoke& iv : invoke)
50	      if (iv.role == role) return &iv.argv;
51	    return nullptr;
52	  }
53	};
54	
55	// Build a descriptor from parsed JSON. Returns "" on success or an error
56	// message naming the first problem (id and type are required).
57	inline std::string descriptor_from_json(const json::Value& v,
58	                                        EngineDescriptor& out) {
59	  if (!v.is_object()) return "descriptor is not a JSON object";
60	
61	  const json::Value* id = v.find("id");
62	  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
63	  out.id = id->as_string();
64	
65	  const json::Value* type = v.find("type");
66	  if (!type || !type->is_string()) return "missing string 'type'";
67	  out.type = type->as_string();
68	
69	  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
70	  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
71	  if (const json::Value* x = v.find("dlen")) out.dlen = x->as_int();
72	  if (const json::Value* x = v.find("elen")) out.elen = x->as_int();
73	  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
74	  if (const json::Value* x = v.find("ilm_size")) out.ilm_size = x->as_int();
75	  if (const json::Value* x = v.find("dlm_size")) out.dlm_size = x->as_int();
76	  if (const json::Value* x = v.find("hvm_size")) out.hvm_size = x->as_int();
77	  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
78	  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
79	  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
80	  if (const json::Value* x = v.find("andes_csrs"))
81	    out.andes_csrs = x->as_string_array();
82	  if (const json::Value* x = v.find("result")) out.result = x->as_string();
83	
84	  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
85	    for (size_t k = 0; k < inv->keys.size(); ++k)
86	      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
87	  }
88	  return "";
89	}
90	
91	}  // namespace andes_sim
92	
93	#endif  // ANDESIM_ENGINE_DESCRIPTOR_HPP
